  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","accent","word","hold","flick","accentFont","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  word: "video",
  hold: 36,
  flick: 18,
  accentFont: "Instrument Serif",
  fontFamily: "Schibsted Grotesk",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type PinnedWordElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof PinnedWordBase>;

const PinnedWordInner = forwardRef<
  HTMLDivElement,
  PinnedWordElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<PinnedWord>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <PinnedWordBase
          {...(componentProps as unknown as ComponentProps<typeof PinnedWordBase>)}
        />
      </div>
    </Sequence>
  );
});

export const PinnedWord = Interactive.withSchema({
  Component: PinnedWordInner,
  componentName: "<PinnedWord>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
